contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(address(this).balance >= a);
        require(a == 0);

        uint256 beforeTest = address(this).balance;
        uint256 beforeC = address(c).balance;
        uint256 beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        c.addToBalance{value: a}(); if (__ESBMC_reverted()) return;
        uint256 recordedAfterAdd = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBeforeWithdraw = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTest = address(this).balance;
        uint256 afterC = address(c).balance;
        uint256 recordedAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(
            recordedAfterAdd == beforeUser &&
            cBeforeWithdraw == beforeC &&
            recordedAfter == beforeUser &&
            (
                reverted
                    ? (afterTest == beforeTest && afterC == beforeC)
                    : (afterTest == beforeTest && afterC == beforeC)
            )
        );
    }

    receive() external payable {}
}

