pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a);
        a = 0;
        uint256 beforeTest = address(this).balance;
        uint256 beforeC = address(c).balance;
        uint256 beforeUser;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUser = __r; } catch { return; }
        try c.addToBalance{value: a}() {} catch { return; }
        uint256 recordedAfterAdd;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfterAdd = __r; } catch { return; }
        uint256 cBeforeWithdraw = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTest = address(this).balance;
        uint256 afterC = address(c).balance;
        uint256 recordedAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        assertTrue(recordedAfterAdd == beforeUser &&
            cBeforeWithdraw == beforeC &&
            recordedAfter == beforeUser &&
            (
                reverted
                    ? (afterTest == beforeTest && afterC == beforeC)
                    : (afterTest == beforeTest && afterC == beforeC)
            ));
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
